/**
 * Starter question bank built from the exercises in the course material, with answer keys
 * written in American English (the book has no answer key; the .docx keys were reviewed and fixed).
 */
import type { QuestionType } from './types';

export interface SeedQuestion {
  topic: string;
  type: QuestionType;
  instruction: string;
  prompt: string;
  options?: string[];
  answer: string;
  accepted: string[];
  explanation: string;
}

const TR = 'Traduza para o inglês';
const CP = 'Complete a frase';
const CH = 'Escolha a alternativa correta';
const NEG = 'Passe para a forma negativa';
const INT = 'Passe para a forma interrogativa';
const Q = 'Escreva a pergunta para esta resposta';

function ch(topic: string, prompt: string, options: string[], correct: number, explanation: string, instruction = CH): SeedQuestion {
  return { topic, type: 'choice', instruction, prompt, options, answer: options[correct], accepted: [options[correct]], explanation };
}

function wr(topic: string, instruction: string, prompt: string, accepted: string[], explanation: string): SeedQuestion {
  return { topic, type: 'writing', instruction, prompt, answer: accepted[0], accepted, explanation };
}

